// Sidebar for one synced docs instance. Groups come from docs-structure.json; any page
// that exists in synced-docs/<id>/ but is not listed lands in "More", so a new page added
// in drt needs no change here and never breaks the build. Sections with no groups
// (adr, migration) are autogenerated from the directory.
const fs = require('fs');
const path = require('path');
const structure = require('../docs-structure.json');

module.exports = function buildSidebar(id) {
  const section = structure[id] || {};
  if (!section.groups) return {docs: [{type: 'autogenerated', dirName: '.'}]};
  const dir = path.join(__dirname, '..', 'synced-docs', id);
  const existing = new Set(
    fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => /\.mdx?$/.test(f)).map((f) => f.replace(/\.mdx?$/, '')) : [],
  );
  const listed = new Set();
  const categories = section.groups
    .map((group) => {
      const items = group.items.filter((item) => existing.has(item));
      items.forEach((item) => listed.add(item));
      return {type: 'category', label: group.label, collapsed: false, items};
    })
    .filter((category) => category.items.length > 0);
  const rest = [...existing].filter((item) => !listed.has(item)).sort();
  if (rest.length) categories.push({type: 'category', label: 'More', collapsed: false, items: rest});
  return {docs: categories};
};
